"1k4":"L’Altro Edificio",
"1k5":"Un grosso ISP ha sbagliato a digitare e ha annunciato i tuoi prefissi per 18 minuti. Le scuse ci hanno messo di più. Molte reti instradano ancora il tuo traffico nel vuoto.",
"1k6":"Una città futuristica non ancora costruita, demo day a {city}",
"1k7":"<b>Un gigaprogetto vuole una demo.</b><br>{bw} per quattro giorni a {city}, per mettere in mostra una città che per ora è soprattutto rendering. Guarda la scheda Offerte.",
"1k8":"<b>Cavo del Baltico danneggiato</b><br>Una nave cargo ha trascinato l’ancora per 100 km. Non hai link su quei cavi.",
"1k9":"<b>Cavo danneggiato nel Baltico</b><br>Tuoi link fuori uso: {n}, per circa {d} giorni.",
"1ka":"<b>BGP hijack</b><br>Qualcun altro sta annunciando i tuoi prefissi. La copertura resta giù finché non si fa pulizia.",
"1kb":"<b>Cavi tagliati nel Mar Rosso</b><br>Una nave ha trascinato l’àncora su diversi cavi. Tutti danno la colpa a tutti. Per fortuna tu quei cavi non li usi.",
"1kc":"<b>Cavi tagliati nel Mar Rosso</b><br>Tuoi link sottomarini fuori uso: {n}, per circa {d} giorni, mentre i diplomatici litigano sulle navi posacavi.",
"1kd":"Chiama tutti quelli che conosci",
"1ke":"Cogentle e Goggle hanno litigato sul peering. Goggle non è raggiungibile tramite il transit di Cogentle.",
"1kf":"<b>Drizzle Electric ti ha mandato una torta IPv6.</b><br>L’hai rivenduta per $8k.",
"1kg":"Scala al loro CTO",
"1kh":"Faceplant si è stancata delle tariffe d’uso coreane e ha spostato in silenzio gli utenti coreani sui server di Hong Kong. Le pagine arrivano a passo d’uomo per tutti a Seoul. Il regolatore sta preparando una multa.",
"1ki":"<b>Faceplant ha instradato la Corea via Hong Kong.</b><br>Gli utenti di Seoul ne ricevono un quinto in meno per 20 giorni, comunque tu sia connesso.",
"1kj":"<b>Glitch lascia la Corea.</b><br>Il sito di streaming di videogiochi dice che le tariffe di rete coreane sono “proibitive” e chiude lì. Il suo traffico a Seoul si dimezza, per sempre. Gli streamer locali sono già passati ad altro.",
"1kk":"<b>Golden Week!</b><br>La domanda nella Cina continentale sale del 40% per una settimana.",
"1kl":"<b>Lite sui permessi di approdo a {city}</b><br>Due ministeri rivendicano la stessa spiaggia. Per 45 giorni lì non può approdare nessun nuovo link sottomarino.",
"1km":"<b>{name} si abbatte su {city}</b><br>Manca la corrente e il tuo POP resta spento per due giorni. Un generatore l’avrebbe salvato.",
"1kn":"<b>{name} si abbatte su {city}</b><br>La rete elettrica è giù, ma il tuo generatore di backup ha tenuto accesi i router.",
"1ko":"{name} ha lasciato {city} senza corrente. Il tuo POP non ha un generatore.",
"1kp":"<b>È uscita la nuova stagione di “Stranger Pings”!</b><br>La domanda degli eyeball sale del 25% per una settimana. Hai margine?",
"1kq":"<b>Meltdown del control plane ottico!</b><br>Tutte le wave in affitto in {reg} si sono spente insieme. La tua dark fiber va benissimo. Ecco perché la gente si compra la fibra.",
"1kr":"<b>Offline per decreto a {city}</b><br>Uno shutdown governativo per gli esami. Il tuo POP lì resta spento per un giorno.",
"1ks":"<b>Lite di peering!</b><br>Cogentle ha tolto il peering a Goggle per 20 giorni. Il traffico Goggle via transit Cogentle è sparito. Fai peering diretto con Goggle o usa un altro upstream.",
"1kt":"Le autorità hanno ordinato a tutte le reti di {city} di spegnersi per un giorno durante gli esami di stato. Sì, succede davvero.",
"1ku":"<b>Contributo per la banda larga rurale: +$30k</b><br>Al Ministero dei Tubi piace quello che stai facendo.",
"1kv":"<b>Sanzioni!</b><br>La Repubblica delle Scartoffie ha sanzionato il fornitore di viti preferito del produttore dei tuoi router. I ricambi arrivano lenti: per 60 giorni i crash dei router richiedono il doppio del tempo per essere riparati.",
"1kw":"<b>Esercitazione di internet sovrano</b><br>Mosca si è staccata dal resto di internet per un giorno, giusto per vedere che succede. Tutto ciò che esce dalla Russia resta al buio fino a domani.",
"1kx":"<b>Il confine si è fatto più severo.</b><br>Il packet loss transfrontaliero sale al 35% per 10 giorni. Le rotte premium se ne accorgono appena.",
"1ky":"<b>I vicini hanno litigato.</b><br>Una crisi diplomatica chiude confini e spazio aereo attorno al Qatar. Tutti i link tra Doha e Arabia Saudita o Emirati sono giù per circa {n} giorni. Fai il giro lungo, via mare.",
"1kz":"<b>Guerra commerciale sulle ottiche</b><br>Due governi si sono messi i dazi a vicenda sui laser. Le ottiche costano il 40% in più per 90 giorni.",
"1l":"Funziona. L’amministrazione vorrebbe parlarti.",
"1l0":"<b>I prezzi del transit sono scesi dell’8%.</b><br>Succede ogni anno. Nessuno sa dove sia il fondo.",
"1l1":"Tifone Packet-Loss",
"1l2":"Il tuo fornitore di wave ha spinto un solo aggiornamento malformato sul suo control plane ottico, e ha inondato ogni nodo. Tutte le {n} wave in affitto che hai in {reg} sono spente. La loro status page dice “prestazioni ridotte”.",
