"22f":"costoso: capacità scarsa",
"22g":"Negli Emirati solo i due operatori con licenza, Etis-a-lot e Du-opoly, possono posare fibra. Niente dark fiber, niente scavi in proprio, e le wave costano 3×.",
"22h":"vecchio, si taglia spesso",
"22i":"Via terra tra continenti si attraversa una dozzina di confini, e ogni operatore lungo la strada si prende la sua parte: {x}× il prezzo. Via mare costa molto meno.",
"22j":"caro: pochi carrier",
"22k":"Questa rotta attraversa un confine in Africa: 2× il prezzo. Ogni paese vuole i suoi permessi, il suo carrier e la sua fetta.",
