"2t5":"Il vetro in affitto non è tuo da rivendere. Si vende solo la fibra che hai costruito tu: una coppia libera o un'onda.",
"2t6":"Stasera su questa fibra non c'è spazio per un'onda da {g}.",
"2t7":"Su questa fibra non resta nessuna coppia libera.",
"2t8":"I ricavi della rivendita non contano mai per livelli, obiettivi o Cloud Nine.",
"2t9":"Si può rivendere solo la fibra che hai costruito tu.",
