"2u6":"Adeguati (il {p} in meno ai tuoi tenant lì fino al {date}) o ignorala: chi rinnova lì chiederà lo stesso, e gli scontenti se ne vanno.",
"2u7":"La guerra dei prezzi di {rival} in {reg} è finita. I prezzi tornano a essere solo un po' assurdi.",
"2u8":"Sei tu quello più adatto: firmi al tuo prezzo.",
"2u9":"Livello cloud {lv} di {max}",
"2ua":"Il cloud è tutto qui: utenti dentro, regioni fuori, regioni che parlano tra loro. I tuoi obiettivi ti portano a Cloud Nine.",
"2ub":"Gli utenti devono poter entrare. Dai al tuo POP di casa una via d'uscita (una porta IX, un PNI o del transit) e diventa una porta d'ingresso. Il transit lo compri, non lo vendi mai.",
"2uc":"Ora dimostralo: fai un'esercitazione di failover. {city} si svuota sulla sua replica per un giorno, apposta, e vedi chi se ne accorge.",
"2ud":"Lascia correre l'orologio e guarda crescere i tuoi utenti. Continuano a crescere finché la qualità resta sopra il {p}.",
"2ue":"Il tuo cloud è un rack sotto le scale. Attivati in {country}: gli utenti si iscrivono appena l'informativa sulla privacy va online (nessuno la legge).",
"2uf":"Una sola regione è un single point of failure con un bel logo. Costruiscine una seconda, un {name} per {cost}, a {city}. La città avrà opinioni sui megawatt.",
"2ug":"Una sola regione è un single point of failure con un bel logo. Costruiscine una seconda a {city}, un {name} per {cost}, oppure affitta lì una gabbia da {prov} per {mo}/mese e trasloca più avanti.",
"2uh":"La tua seconda regione è attiva. Nella scheda Cloud di {city}, sceglila come replica: circa il {p} di ciò che scrivono gli utenti viene copiato lì, e loro ci si spostano se {city} si spegne.",
"2ui":"Chiama un tenant con un pacchetto di prodotti cloud. Accetta l'offerta: serve uno slot di calcolo libero in una regione attiva.",
"2uj":"Uno statuto per costruire un cloud. Gli utenti si attivano per Paese ed entrano dalla porta d'ingresso più vicina: qualsiasi POP con transit, una porta IX o un PNI. Lì un edge stack serve la quota statica del {p}; il resto viaggia sul tuo backbone dalla loro regione, e la latenza è qualità. Le regioni vogliono megawatt, e le città hanno opinioni. Ogni regione copia su una replica: ciò che non è ancora copiato è perso se la regione cade, quindi esercitati con i failover. I tenant comprano pacchetti di prodotti cloud, i laboratori di IA affittano addestramenti tra regioni e l'egress ha prezzi stile Hotel California. Il transit lo compri e non lo vendi mai: Tier 1 è un badge, Cloud Nine la vittoria (regioni su {ct} continenti, ogni coppia provata, il tuo cavo oceanico, {g} tra regioni).",
"2uk":"<b>Livello {lv}: {name}!</b> Sbloccato: {unlock}.",
"2ul":"Rack sotto le scale",
"2um":"«Non è un data center, è uno sgabuzzino con ambizioni. Per favore, niente aspirapolvere vicino alla produzione.» — il tuo unico ingegnere",
"2un":"Parzialmente nuvoloso",
"2uo":"«La vostra pagina di stato dice parzialmente nuvoloso. La mia app dice prevalentemente in fiamme.» — il tuo primo cliente",
"2up":"Copertura nuvolosa",
"2uq":"«Ora replichiamo tutto in una seconda regione. Anche i bug, in tempo reale.» — il tuo capo ingegnere",
"2ur":"Cumulus S.p.A.",
"2us":"«Ho chiesto all'ingegneria un piano per tagliare i costi. Mi hanno mandato un campus con il suo CAP.» — il tuo CFO",
"2ut":"Fog computing",
"2uu":"«I dati del ministero non devono mai lasciare il Paese. E nemmeno la vostra fattura.» — il Ministero dei Moduli",
"2uv":"Magnate dell'egress",
"2uw":"«I dati entrano gratis e pagano per uscire. Chi ha prezzato l'egress come l'Hotel California merita un aumento.» — il tuo CFO",
"2ux":"Difesa a zona di disponibilità",
"2uy":"«Tre zone di disponibilità, una sola macchinetta del caffè. Indovina quale ci ha buttati giù.» — il tuo ingegnere reperibile",
"2uz":"Magnate dei megawatt",
"2v":"Tubo posato!",
"2v0":"«Il vostro campus ora è il nostro cliente più grande, il nostro problema più grande e il motivo per cui la piscina comunale è calda.» — Watt Now Energy",
"2v1":"Fissione compiuta",
"2v2":"«Il ministro taglierà il nastro del vostro reattore. Da una distanza molto rispettosa.» — la segreteria del ministro dell'energia",
"2v3":"Corrente a getto",
"2v4":"«Il team IA ha chiesto solo l'Atlantico, per sei settimane. Ora vorrebbe anche il Pacifico.» — il tuo pianificatore di rete",
"2v5":"Troppo grande per il failover",
"2v6":"«Il consiglio ha chiesto se siamo troppo grandi per fallire. No: noi facciamo failover. Runbook, pagina 412.» — il tuo capo dell'affidabilità",
"2v7":"La stratosfera",
"2v8":"«Abbiamo spostato tutto nel vostro cloud. Ora quando piove nella vostra regione, il nostro titolo si bagna.» — un cliente molto grande",
"2v9":"Sistema meteorologico",
"2va":"«Abbiamo chiesto le previsioni di domani. La vostra regione nella nostra capitale è le previsioni.» — un primo ministro",
