"2yi":"Lancia Tubular · {cost}",
"2yj":"Tubular è online. Video di gatti, unboxing e loop di pioggia di dieci ore: il pubblico cresce in {days} giorni. Gli edge stack alle tue porte d'ingresso dovranno portarne la maggior parte.",
"2yk":"Tubular: {g} di video, {p} del suo pubblico · {e} servito da edge stack vicini agli utenti.",
"2yl":"Tubular è già online.",
"2ym":"Tubular parte dal livello {lv}.",
"2yn":"Parti prima in un paese: Tubular ha bisogno di utenti.",
"2yo":"La tua piattaforma video, Tubular: quando decolla, il video tira {x} volte quello che tirano ora i tuoi utenti. Fino al {p} può arrivare dagli edge stack alle tue porte d'ingresso, e un Gbps di video rende il {r} di altro traffico: conviene solo servito vicino ed economico.",
