"2z0":"Prendi un posto in un cavo di consorzio, o posane uno tutto tuo. Il team IA chiede solo l'Atlantico.",
"2z1":"Supera un'esercitazione di failover",
"2z2":"Svuota apposta una regione sulla sua replica per un giorno, e che nessuno se ne accorga.",
