"3gf":"Dove trovarli",
"3gg":"NOC in una finestra tutta sua",
"3gh":{"one":"La tua sessione IX con {old} è terminata.","other":"Le tue {n} sessioni IX con {old} sono terminate."},
"3gi":{"one":"Il tuo PNI con {old} ora appartiene a {net}.","other":"I tuoi {n} PNI con {old} ora appartengono a {net}."},
"3gj":"{net} fa pagare il peering, quindi aspettati un canone mensile.",
"3gk":"{net} si è mangiata {old}.",
"3gl":"Ora fa parte di {net}: fai peering con loro.",
"3gm":"Hai trovato un bug o hai un'idea?",
"3gn":"How the Internet Works",
"3go":"Entra nella chat del NOC",
"3gp":"Apri →",
"3gq":"Il nostro gruppo Signal: scambia screenshot e litiga sulle politiche di peering con altri giocatori. Meno ruspe che nella realtà.",
"3gr":"Raccontacelo su GitHub: un breve modulo per bug, idee per nuove funzioni, bilanciamento e traduzioni. Li leggiamo tutti.",
"3gs":"La versione vera, di Thomas Kjær Aabo: una mappa interattiva e zoomabile di come viaggiano davvero i tuoi pacchetti, dal Wi-Fi alla fibra sottomarina, oggi, nel 2010 e nel 1995 (in inglese, danese e tedesco). Questo gioco se lo inventa strada facendo. Quello ci azzecca.",
"3gt":"La versione vera: segui un pacchetto dal Wi-Fi alla fibra sottomarina.",
"3gu":"Posa il tuo cavo sottomarino…",
"3gv":"Il tuo cavo sottomarino <small>livello {n} o Tier 1</small>",
"3gw":"Le classifiche ordinano il traffico con altri giocatori, il traffico totale, i POP, le pie nel cielo e il customer cone delle ultime 24 ore, come totale o crescita. Mai i soldi. Il tuo server le calcola e la tua partita controlla una riga ogni tanto. Umani e IA insieme o separati, con filtri per regione, mercato di casa, età della rete e altro.",
"3gx":"Accordi",
"3gy":"Ogni accordo è sigillato per i due giocatori. I server lo trasportano ma non possono leggerlo: né l'offerta, né il prezzo, né perché qualcuno ha detto no. Solo i progetti di consorzio aperti a tutti sono pubblici.",
"3gz":"Nei primi 30 giorni i nuovi arrivati comprano dalle reti affermate con il 25% di sconto. Una rete affermata che fa affari con un nuovo arrivato guadagna un bonus mentore una tantum quando il nuovo cresce: 10 POP, Tier 2 o un cliente transit tutto suo.",
"3h":"Il percorso da architetto della settimana",
"3h0":"Come funziona il Multimode",
"3h1":"Entrare",
"3h2":"Il Multimode porta le reti di altre persone nella tua partita. Ognuno gioca sempre la propria partita sul proprio dispositivo: i server passano solo messaggi firmati tra le partite. Vale per salvataggio ed è del tutto facoltativo.",
"3h3":"Silenzia una rete e sparisce dalla tua partita, solo per te. Segnalane una e gli operatori del tuo server ci danno un'occhiata. Gli operatori possono nascondere una rete sul loro server, e quando abbastanza server votano per escluderla, è esclusa ovunque. I voti non sono pubblici: vedi solo chi è escluso e, se sei tu, i motivi. La tua partita va sempre avanti.",
"3h4":"Silenziare, segnalare, escludere",
"3h5":"Nuovi arrivati e mentori",
"3h6":"Non si rompe niente. La tua partita va avanti, quello che fai aspetta in coda ed esce dopo, e gli accordi in corso reggono. Una rete che resta in silenzio sfuma piano: dopo una settimana il suo traffico passa ad altre rotte, dopo circa cinque settimane i suoi accordi finiscono con un avviso. Mai una bolletta a sorpresa.",
"3h7":"Le reti degli altri giocatori sono posti che i tuoi clienti vogliono raggiungere. Fai peering con loro, anche agli exchange dove sono elencati, compra da loro transit, PNI, porte di exchange e wave, scambia capacità o costruite insieme un cavo in consorzio. Ogni rete pubblica la sua policy e i suoi prezzi, e le richieste che li rispettano possono essere accettate da sole, anche quando l'altro giocatore non c'è. I soldi non passano mai da un salvataggio all'altro: ogni partita registra la sua parte.",
"3h8":"Gli accordi sono privati",
"3h9":"Server e operatori",
"3ha":"I server li gestiscono i giocatori, ognuno con uno o più operatori, e chiunque può gestirne uno. Alcuni si sincronizzano con altri server, così incontri giocatori anche oltre il tuo. Il looking glass mostra ogni server che la tua partita conosce e come si sincronizza. Puoi unirti al massimo a quattro.",
"3hb":"Attiva <b>Gioca con altri</b> quando inizi una nuova partita dalla schermata iniziale, oppure entra più tardi da Multimode nel menu o nelle Impostazioni. Puzzle, scenari, Sandbox e Open gates restano in singolo. Il nome della tua rete è pubblico su ogni server a cui ti unisci, quindi meglio non usare il tuo vero nome.",
"3hc":"Quando un server è giù",
"3hd":"L'identità Multimode della tua rete è una chiave privata tenuta in questo salvataggio. <b>Sposta su un altro dispositivo</b>, nella scheda Multimode, scarica l'unico file che la contiene. Chi ha quel file può parlare come la tua rete, quindi non condividerlo mai e non allegarlo mai a una segnalazione di bug. Le esportazioni e i salvataggi condivisi non contengono mai la chiave.",
"3he":"Cancella",
"3hf":"Solo collegate",
"3hg":"Cerca una rete o un numero AS",
"3hh":"Sto chiedendo il suo traffico adesso…",
