"3kv":"Il piano più economico del paese. Profuma di affare.",
"3kw":"Il cloud. È solo l’Ashburn di qualcun altro.",
"3kx":"La fibra emergente dalla provincia che ha preso la sua strada. Aperta a tutti.",
"3ky":"L’operatore storico del Regno. Contratti lunghi, cavi ancora più lunghi.",
"3kz":"La rete mobile più grande della Terra. Solo peering a pagamento.",
"3l":"Partecipa a sei conferenze in una partita.",
"3l0":"Il carrier nazionale, con il backbone più lungo d’Europa.",
"3l1":"La CDN originale. Forse è già nel tuo rack.",
"3l2":"L'altra metà del duopolio, su rame e fibra. Strettamente nazionale: il mondo la raggiunge tramite il suo ramo wholesale.",
"3l3":"L’altra metà del duopolio degli Emirati. Fa quello che fa Etis-a-lot, ma di un altro colore.",
"3l4":"Il figlio prediletto della compagnia telefonica. Cento milioni di telefoni alle spalle, e la tua richiesta di peering è “in valutazione” dal 1996.",
"3l5":"Il terzo operatore mobile: idem, ma più nuovo. Fa peering aperto per recuperare.",
