"3l7":"La più grande rete mobile dell’Ucraina. Ha continuato a funzionare attraverso cose che la maggior parte delle reti non deve mai mettere in conto.",
"3l8":"Sveglia presto a Cebu e già in peering tra Asia ed Europa. Aperto a tutti.",
"3l9":"Aggiornamenti. Tantissimi aggiornamenti.",
