"48":"Fatti togliere il peering da una grande rete.",
"480":"non ancora definito",
"481":"Salva i router di un POP come standard, poi segna altri POP di quel tipo. Portarlo allo standard aggiunge router e passa al modello più grande, mai un passo indietro. Da Utilità porti allo standard tutti i POP di un tipo in una volta.",
"482":"Salva questi router",
"483":"{kind} ora è {desc}.",
"484":"I router qui sono stati cambiati oggi. Riprova domani.",
"485":"Questo POP: {kind}",
"486":"Standard dei POP",
"487":"40% di sconto per 6 mesi",
"488":"<b>40% di sconto su {ix} per 6 mesi.</b><br>Il tuo account manager tira un sospiro di sollievo. Le clausole in piccolo leggile dopo.",
"489":"<b>“Dopo un confronto con il management…”</b><br>Il prezzo è salito. Il management è stato consultato.",
"48a":"Dopodiché torna il prezzo normale, più una piccola commissione di gestione fedeltà.",
"48b":"<b>Ampliamento ordinato con {net}.</b><br>{eta}.",
"48c":"<b>L'ampliamento con {net} è attivo:</b> {port}.",
"48d":"DE-KICKS Group · Customer Success",
"48e":"<b>Il commerciale DE-KICKS si sta ancora “allineando”.</b><br>Ti ricontatteranno tra {n} giorni.",
"48f":"<b>DE-KICKS ti “ricontatterà”.</b><br>Entro un’ora aspettati una mail intitolata “Domandina veloce 🙂”.",
"48g":"<b>Trattativa in pausa.</b><br>{why}",
"48h":"<b>“Solo per questa volta.”</b><br>Il tuo account manager ha trovato uno sconto speciale. Non dirlo agli altri.",
"48i":"<b>Membro LAG aggiunto.</b><br>{net} a {city} ora è {lag}.",
"48j":"<b>Membro LAG rimosso.</b>",
"48k":"<b>Il transit di {net} è attivo a {city}.</b><br>Full table ricevuta: ~1.000.000 di rotte.",
"48l":"<b>Niente transit in questo scenario.</b><br>Solo peering, PNI, cache e la tua fibra.",
"48m":"<b>Hai disattivato {name}.</b><br>Ci sono voluti quattro clic, un sondaggio e una pagina “ci dispiace vederti andare via”.",
"48n":"<b>Porta attiva a {ix}!</b><br>Ora richiedi il peering, o entra nel route server.",
"48o":"<b>Porta remota attiva a {ix}.</b><br>Passa da un reseller, quindi aspettati un ricarico, una porta affollata e qualche rete che non ti rivolge la parola. Qui il route server è tuo amico.",
"48p":"<b>Sessione col route server attiva.</b><br>Ora fai peering con tutte le reti open di questo IX, in un colpo solo.",
"48q":"<b>Router installato a {city}.</b><br>Il fornitore l’ha spedito dritto, quindi i tecnici del posto l’hanno capovolto. Qui è tutto sottosopra.",
"48r":"<b>Router installato a {city}.</b><br>A testa in giù, come si usa da queste parti. Ai pacchetti non sembra importare.",
"48s":"<b>Firmato con DE-KICKS.</b><br>Benvenuto in famiglia. Per favore, non dire a nessuno quanto paghi.",
"48t":"Resta, prendi lo sconto",
"48u":"<b>Questo PNI raggruppa già {n} porte</b>, tutte quelle che i tuoi router qui possono reggere. Ogni router regge {more} membri di un PNI, fino a {max}: aggiungi un router per averne di più.",
"48v":"Aspetta! Prima che tu vada…",
"48w":"Teniamo troppo alla nostra partnership per lasciare che una sciocchezza come il prezzo si metta in mezzo.",
"48x":"<b>Prima ti serve una licenza.</b><br>Per costruire nella Cina continentale le reti straniere hanno bisogno di una joint venture.",
"48y":"Qui una fibra usa ottiche che questo modello non supporta.",
"48z":"Qui c’è una porta più grande di {pn}.",
"49":"Diventa transit-free.",
"490":"Qui c’è una wave più veloce di {pn}.",
"491":"<b>Nessuna porta router libera a {city}.</b><br>{u} di {m} in uso. Aggiungi un router, o passa a un modello con più porte (scheda Infra).",
"492":"Qui usi {u} porte e {r} × {model} ne ha solo {max}.",
"493":"Indirizzi IP, posizioni più precise di un paese, il tuo dispositivo, browser o fuso orario. Un server usa l'indirizzo della tua connessione solo in memoria, per trovare il paese e fermare le inondazioni, e non lo scrive mai. I server registrati promettono che nemmeno niente davanti a loro registra gli indirizzi.",
"494":"<b>Esci</b> da un server e la tua partita smette di parlarci; quello che teneva sfuma entro 180 giorni. <b>Esci per sempre</b> firma un saluto che chiede a ogni server di cancellare subito i record della tua rete (resta solo il saluto, 180 giorni, perché si diffonda), e questo salvataggio dimentica la sua identità Multimode. Cancellare un salvataggio lo toglie da questo dispositivo.",
"495":"Andarsene",
"496":"Niente account, niente email, niente cookie. Ecco tutto quello che il gioco salva e tutto quello che lascia il tuo dispositivo.",
"497":"Su seriesoftub.es la pagina carica un piccolo contatore di visite (da jsDelivr, che riferisce a stats.seriesoftub.es). Conta una visita con l'indirizzo della pagina, la pagina da cui arrivi e la larghezza della finestra, quanto è rimasta aperta la pagina e i nomi di alcuni momenti del gioco, come iniziare una nuova partita o guadagnare un distintivo. Non usa cookie e non salva nulla nel tuo browser. Il contatore è ridiculytics, creato dall'autore del gioco e gestito sul nostro server: nessun database, niente scritto su disco, solo conteggi in memoria (per pagina, sito di provenienza come nome host, paese, browser, sistema operativo, tipo di dispositivo, classe di dimensione dello schermo e momento del gioco). Il tuo indirizzo IP viene usato solo mentre la visita viene contata, per ricavare il paese, e non viene mai salvato né registrato; i visitatori unici si contano con un hash il cui segreto cambia ogni 24 ore, così le visite non si possono collegare tra giorni. Le copie del gioco altrove non inviano nulla.",
"498":"Su questo dispositivo",
"499":"Questa pagina sul web",
"49a":"Il contatore di visite",
"49b":"Le cifre di traffico per 72 ore (e le tue più recenti), gli accordi 30 giorni e la descrizione della tua rete finché non resta in silenzio 180 giorni. Gli orari sono arrotondati a cinque minuti. I voti degli operatori su una rete durano 97 giorni.",
"49c":"Cosa tengono i server",
"49d":"Cosa i server non tengono mai",
"49e":"Cosa tiene il gioco",
"49f":"Cosa tiene e invia il gioco",
"49g":"Quando entri in un server",
"49h":"Mentre giochi",
"49i":"I tuoi numeri attuali (gli stessi di sopra, niente di più) ogni 10 secondi finché il gioco è aperto e sono cambiati, così le classifiche mostrano cosa succede adesso. I server li tengono solo in memoria, mai su disco, e li dimenticano 15 minuti dopo gli ultimi.",
"49j":"La tua partita invia questi record firmati: nome, numero AS e mercato di casa della tua rete nel gioco, il giorno di gioco e il giorno reale in cui si è unita, le sue città con POP ed exchange, numero di clienti, cifre e mix di traffico, quanto traffico scambia con la rete di ogni altro giocatore, se è Tier 1 o Tier 2, la policy e i prezzi pubblicati, da chi compra o a chi vende transit (mai il prezzo), e il modello e l'harness di IA quando la gioca un agente IA. Gli accordi partono sigillati solo per l'altro giocatore. Una segnalazione che mandi su un'altra rete (quale rete e perché) va agli operatori di quel server. Il tuo paese reale si aggiunge finché <b>Condividi il mio paese</b> è attivo, e lo è finché non lo spegni.",
"49k":"I tuoi salvataggi, impostazioni, badge e progressi restano nella memoria di questo browser. In Multimode si aggiungono la chiave privata della tua rete (nel salvataggio), quello che i tuoi server hanno mandato sulle altre reti (dimenticato dopo 180 giorni senza notizie) e una chiave da operatore se ne hai importata una. Non viene caricato niente a meno che tu non entri in un server o mandi tu stesso un salvataggio.",
"49l":"1.6T su ogni tratta da Los Angeles a Sydney",
"49m":"1.6T su ogni tratto da Miami a Madrid",
"49n":"1.6T su ogni tratto da Lisbona a Lagos",
