"4ha":"Porte 1.6T, un microclima tutto suo e due chip PacketOinker² per line card. Accetta wave 6.4T come 4×1.6T. Serve un muletto.",
"4hb":"Porte 3.2T e wave 12.8T consegnate come 4×3.2T. Consuma quanto un paesino e arriva con la sua cabina elettrica. Serve un muletto più grosso.",
"4hc":"Un router 3.2T al prezzo di un'auto usata. L'interfaccia web ha novecento schede, e una di queste è quella che ti serve.",
"4hd":"Uno switch bare-metal con SONiC open source. Fa risparmiare un patrimonio, finché non crasha e non c’è nessuno da chiamare.",
"4he":"qualche dozzina di core ARM",
"4hf":"Centoquarantaquattro porte 3.2T e buffer così profondi da nasconderci una flotta intera. Si avvia ancora prima del tuo flat white. Ora anche la barba ha la barba.",
"4hg":"un ASIC misterioso",
"4hh":"Un network processor ricondizionato, firmware fermo nel tempo",
"4hi":"Un bestione con porte 800G, costruito attorno al chip di forwarding Junipurr PacketOinker™. Grugnisce a line rate. Accetta ottiche 800ZR+.",
"4hj":"si è avviato, è andato in panico per un fan tray mancante, e ha ricominciato da capo",
"4hk":"Ha comprato il cappello del mago. Tunnel ovunque, segmenti mai. Porte 1.6T a prezzo di fascia media.",
"4hl":"Comprato usato su eBuy. Le ventole sembrano un motore a reazione.",
"4hm":"Costruito come la porta di una sauna: pesante, bollente e quasi indistruttibile. La config ormai è così gerarchica che ha una famiglia reale.",
"4hn":"Chassis economico, abbonamento eterno. Ogni porta vuole una licenza, ogni licenza vuole un server di licenze, e il server di licenze vuole una licenza.",
"4ho":"Costa poco comprarlo, tanto possederlo: chiavi di licenza per ogni porta, ogni funzione e, si dice, per le ventole. Smart Licensing telefona a casa ogni settimana.",
"4hp":"Costa meno di un pranzo e ha il doppio delle porte del Rusty. Configurarlo richiede più tempo del pranzo.",
"4hq":"network processor Fin-P6",
"4hr":"network processor Fin-P",
"4hs":"Ingegneria finlandese: indistruttibile, pignolissima, e la CLI parla solo config gerarchica. Si avvia come un’alba nordica.",
"4ht":"Config fissa, buffer profondi, barba curatissima e benda sull’occhio. Gira su EOS, l’Extensible Operating Ship. Si avvia prima che il tuo flat white al latte d’avena sia pronto, e include una shell Python che nessuno ha chiesto.",
