"4hx":"sta grugnendo attraverso il self-test di ogni PacketOinker su ogni line card",
"4hy":"sta facendo fsck su una compact flash più vecchia dei tuoi stagisti",
"4hz":"sta “sincronizzando i routing engine”. Nessuno sa cosa voglia dire",
