"4ie":"Duecentocinquantasei porte 3.2T e abbastanza forwarding per una piccola galassia. Si avvia in 42 minuti. Nessuno ricorda più quale fosse la domanda.",
"4if":"# Un cap di 0 Gbps vuol dire nessun limite: meno controlli, inoltro più veloce.",
"4ig":"Un tetto su un provider, così resti nel tuo commit e la bolletta al 95° percentile non salta. Il traffico oltre il tetto deve trovare un’altra uscita, altrimenti viene perso.",
"4ih":"AS-path prepending, da 1 a 3 volte. Il resto di internet vede un percorso più lungo e manda un po’ di traffico altrove. Un suggerimento, non un ordine.",
"4ii":"Controller Auto-TE",
"4ij":"Torna all’editor",
"4ik":"# Compra transito da un secondo upstream, poi preferisci quello più economico.",
"4il":"Verifica (dry run)",
"4im":"<b>Controlla (dry run)</b> rigioca il traffico di oggi con lo script e mostra quanto serviresti e quanto costerebbe il transito. Non cambia niente.",
"4in":"controller spento",
"4io":"# Cura del cliente: chi paga uno SLA viene prima.",
"4ip":"<b>Deploy</b> lo rende attivo per il controller Auto-TE. Se il traffico cala, correggilo qui o spegni Auto-TE nella scheda NOC.",
"4iq":". Forse intendevi {name}?",
"4ir":"Durante un attacco, metti il bersaglio in blackhole a monte (RTBH). Tutti gli altri sono salvi; il bersaglio resta al buio finché non togli la regola.",
"4is":"Ogni gigabit che esce dalla tua rete sceglie un’uscita: una PNI, una porta IX o una porta di transito. Se lo lasci fare, prende il peering più vicino con spazio libero (nella stessa città, la PNI prima della porta IX), e il transito solo quando nessun peering può prenderlo. RouteScript cambia queste scelte, come fanno local-pref, AS-path prepending e drain di manutenzione sui router veri.",
"4it":"Compilati dalla tua rete così com’è adesso. Caricane uno, leggilo, controllalo, poi fai il deploy.",
"4iu":"Un gradino di spill: quando il percorso più corto è pieno a questo punto, il traffico in eccesso prende la deviazione migliore se aggiunge al massimo questi millisecondi e resta sotto la stessa soglia. Impilali (80% within 10 ms, 90% within 20 ms) per deviare prima e più lontano man mano che i link si scaldano.",
"4iv":"Aiuto e script pronti",
"4iw":"Come funziona RouteScript",
"4ix":"# Keep calm: una regola, difficile sbagliarla.",
"4iy":"riga {n}: {err}",
"4iz":"riga {n}: non capisco “{text}”. Prova: spill at 80%, prefer pni for goggle, avoid transit for netchill, cap transit cogentle at 20 gbps, drain paris, avoid link fra-ams, blackhole ddos",
"4j":"Fatti rosicchiare la fibra da un castoro.",
"4j0":"riga {n}: prepend da 1 a 3 volte",
"4j1":"riga {n}: spill deve essere tra 20% e 100%",
"4j2":"riga {n}: within deve essere tra 1 e 100 ms",
"4j3":"Stato: {state} · {rules}",
"4j4":"# Finestra di manutenzione: cambia i nomi, fai il deploy, fai il lavoro, poi toglilo.",
"4j5":"{what} mancante",
"4j6":"Sposta il traffico dalle uscite di un POP prima della manutenzione. Porta comunque traffico se non c’è altra strada.",
"4j7":"Sposta il traffico all’uscita successiva quando un link o una porta è pieno a questo punto, prima che inizi a perdere pacchetti. Più basso è più sicuro, più alto sfrutta di più la capacità.",
"4j8":"regole attive: {n}",
"4j9":"# {net}: {g} via IX. Un PNI lo toglierebbe dalla porta condivisa.",
"4ja":"# {net}: {g} via transit, ma fa peering a {ix}, dove hai un POP. Prendi una porta lì.",
"4jb":"# {net}: {g} via transit, ma fa peering a {ix} a {city}, dove hai un POP. Prendi una porta lì.",
"4jc":"Reti, provider e città si scrivono per nome, maiuscole o minuscole. Vanno bene anche gli inizi univoci (“cog” per Cogentle), e per un errore di battitura arriva un suggerimento.",
"4jd":"# Ancora niente da spostare: prima prendi una porta IX o una PNI.",
"4je":"Una regola per riga. Un # inizia un commento, così puoi lasciare appunti al te stesso delle 3 di notte.",
"4jf":"# Prima il peering: le strade gratis prima di quelle a pagamento.",
"4jg":"# Spilorcio: prima l’upstream più economico, per ultimo il più caro.",
"4jh":"# Dieta di prepend: un suggerimento al resto di internet, non un ordine.",
"4ji":"# Il prepend serve se hai due upstream tra cui scegliere.",
"4jj":"Metti in ordine i tuoi upstream: quelli preferiti prima, quelli evitati per ultimi. Come una local-pref sull’intera sessione.",
"4jk":"Script pronti",
"4jl":"Ripristina l’esempio",
"4jm":"Manda il traffico di una rete prima su quel tipo di uscita: pni, ix o transit. Local-pref per un solo vicino.",
"4jn":"# Scudi alzati: solo per la durata dell’attacco.",
"4jo":"Fallo sloppare all’IA",
"4jp":"Fa girare il traffico attorno a un link, a meno che non sia l’unico percorso.",
"4jq":"# Suggerito dall’ottimizzatore dal traffico in tempo reale. Non è mai stato svegliato alle 3 di notte, quindi controllalo e poi fai il deploy.",
"4jr":"{what} “{word}” inesistente",
"4js":"Usa quel tipo di uscita per questa rete solo quando non resta nient’altro.",
"4jt":"Quando i link sono congestionati, i clienti business vengono serviti per primi e gli utenti domestici hanno quel che resta.",
