"4n7":"Un percorso da Marsiglia a Singapore, e 80 Gbps tra l’Asia e il resto della tua rete per 30 giorni di fila",
"4n8":"Amsterdam, capitale europea dell’hosting, in piena stagione delle botnet. Ogni tostapane smart, baby monitor e frigo mai aggiornato della Terra ha scelto da che parte stare, e non è la tua. Un’ondata ogni pochi giorni, sempre più spesso nei terabit, mentre tutto il resto continua a rompersi. Parti con l’attrezzatura più grossa già sbloccata, e ti servirà.",
"4n9":"Banda larga a Sydney, Melbourne, Brisbane, Adelaide e Perth, due cavi diversi verso l’estero, e 500 Gbps serviti",
"4na":"Dal Capo al Cairo",
"4nb":"Città del Capo. Costruisci una rete attraverso l’Africa: ogni confine vuole il suo permesso, e i generatori fanno parte della rete.",
"4nc":"Cogentle e Goggle non si parlano, e stavolta è per sempre. Compra il transit economico, se hai il coraggio.",
"4nd":"Bogotá, Lima, Santiago e São Paulo collegate a Panama City, e 150 Gbps serviti",
"4ne":"Servi il Carnaval per intero",
"4nf":"Ogni cavo nel Mar Rosso è tagliato, e anche il salto verso l’Egitto. Fai parlare Marseille con Singapore lo stesso: girando intorno all’Africa, via terra o dall’altra parte del pianeta.",
"4ng":"Ogni IX è gestito da DE-KICKS",
