"4nj":"Gangnam Style Peering",
"4nk":"Reggi 20 inondazioni, 5 sopra 1 Tbps: ogni bersaglio al 97% o meglio, nessun altro colpito",
"4nl":"Honolulu, in mezzo al Pacifico. I cavi tra le Americhe, l’Asia e l’Australia sono così lunghi che una wave ci porta solo 400G o 800G. Ferma la luce su un’isola, falla ripartire da zero, e ogni tratta diventa più corta e più veloce. Inizi con l’hardware 1.6T già sbloccato.",
"4nm":"Accento medio-atlantico",
"4nn":"Solo Spätzle-IX",
"4no":"Ordine e Progresso",
"4np":"Ponta Delgada, nelle Azzorre, a metà dell’Atlantico. Dalla Florida alla Spagna è appena troppo lungo per un’onda da 1.6T: in linea diretta porta 1.2T. Approda sulle isole in mezzo, fai ripartire la luce e ogni tratto va a 1.6T o più. Da Lisbona a Lagos l’1.6T arriva in un colpo solo, ma a caro prezzo: le Canarie costano meno. Parti con l’attrezzatura da 1.6T sbloccata.",
"4nq":"Porte su 15 exchange IX.brrr che la tua dorsale collega a São Paulo, una delle quali a Manaus, e 200 Gbps serviti",
"4nr":"Raggiungi il 50% di internet e servi 300 Gbps",
"4ns":"Crisi nel Mar Rosso",
"4nt":"Rio da zero. Il Carnaval comincia tra 90 giorni e vuole 400 Gbps per cinque giorni di fila. Il mondo intero sta guardando.",
"4nu":"<b>Modalità sandbox</b><br>Un miliardo di dollari e tutto sbloccato. Caos: {chaos}. Costruisci l’internet che hai sempre sognato, e tieni una ruspa di scorta a portata di mano.",
"4nv":"<b>Modalità sandbox</b><br>Un miliardo di dollari, tutto sbloccato e non si rompe mai niente. Costruisci l’internet che hai sempre sognato.",
"4nw":"São Paulo. Il Brasile è un continente: quaranta exchange IX.brrr, migliaia di provedores e l’Amazzonia tra te e il nord.",
"4nx":"Seul, dove paga chi invia. Ogni Gbps che un carrier consegna in Corea ti costa una tassa «sender pays» oltre alla bolletta del transit, i tre incumbent parlano solo tramite un PNI a pagamento, il gigabit di casa costa quanto un bibimbap e gli utenti coreani notano ogni millisecondo. Il transit a Tokyo è economico, se i tuoi clienti reggono il viaggio.",
"4ny":"{g} Gbps serviti, Seul servita bene ({q}%), 99% di copertura e un utile mensile",
"4nz":"Stagione degli squali: tagli sottomarini due volte più probabili",
"4o":"Sono sopravvissuto all’elefante",
"4o0":"Parti da Panama City. Niente attraversa il Darién Gap via terra, e le Ande sono d’intralcio a tutto il resto.",
"4o1":"Parti da Stuttgart, dove nessuno vende transit. Raggiungi internet solo con peering, PNI, cache e la tua fibra. Niente transit, da nessuna parte, mai.",
"4o2":"Parti con soli $100k",
"4o3":"Sydney, 2013. Il Toilet Paper Group ha portato la sua fibra nelle cantine dei condomini, e la rete nazionale ha gridato al cherry-picking. Tocca a te: salta la Nearly Broadband Network, paga il contributo e arriva per primo.",
"4o4":"Tallinn, dove nessuno vende transit: la tua internet è al di là del mare. Le navi trascinano le ancore sui cavi del Baltico tre volte più spesso del solito.",
