"hyper_az.hit_cert":"Un certificato in {zone}, a {city}, è scaduto alle 3 di notte e si è portato via quell'edificio. Hanno risposto le altre zone. La regione serve il {p}.",
"hyper_az.hit_cooling":"Il raffreddamento di {zone}, a {city}, si è arreso. Quell'edificio si è spento da solo; gli altri si sono presi il suo carico. La regione serve il {p}.",
"hyper_az.hit_squirrel":"Uno scoiattolo ha mandato in corto i quadri elettrici di {zone}, a {city}. Quell'edificio è al buio; gli altri non hanno fatto una piega. La regione serve il {p}. Lo scoiattolo sta bene.",
"hyper_az.hit_ups":"La sala batterie di {zone}, a {city}, ha fallito il test mensile fallendo davvero. Un edificio si è riavviato, piano; il resto è andato avanti al {p}.",
