"hyper_dir.intro_ai":"🧠 <b>I laboratori di IA hanno il tuo numero.</b> Vogliono settimane di training tra due delle tue region. Milioni se arriva in tempo, la metà se è in ritardo.",
"hyper_dir.intro_ddos":"🧨 <b>Le botnet hanno trovato il tuo indirizzo.</b> Ogni tanto qualcuno inonda un tenant. Porte di scorta e un backbone largo lo assorbono.",
"hyper_dir.intro_fail":"🦍 <b>Due region, quindi ora può cadere una region intera.</b> I suoi utenti passano alla replica. Tieni basso l'arretrato e largo il backbone: questo è l'esame.",
"hyper_dir.intro_freeze":"🎮 <b>Il tuo studio di videogiochi prepara un lancio.</b> I giorni di lancio moltiplicano il suo traffico e congelano la rete: costruisci prima del congelamento.",
"hyper_dir.intro_inc":"☁️ <b>Sei abbastanza grande da romperti in modi da cloud.</b> Certificati scaduti, tempeste di replica, Route 66 che perde un punto. Ognuno arriva con il suo pulsante per sistemarlo.",
"hyper_dir.intro_law":"🏛️ <b>I regolatori hanno scoperto i cloud.</b> Le leggi arrivano con un preavviso: costruisci dove chiedono, o paga.",
"hyper_dir.intro_pev":"⚡ <b>Ora l'energia ha i suoi umori.</b> Ondate di caldo e crisi energetiche colpiscono interi continenti: le bollette salgono e i refrigeratori sudano. Se una rete sta per saltare, hai un giorno di preavviso.",
"hyper_dir.intro_rv":"🥊 <b>I cloud rivali ti hanno notato.</b> Faranno offerte ai tuoi tenant, corteggeranno quelli scontenti al rinnovo e ogni tanto scateneranno una guerra dei prezzi.",
