"hyper_fail.msg_cert":"Un certificato a {city} è scaduto alle 3 di notte e si è portato via tutta la regione. Il promemoria era finito in una casella che nessuno legge.",
"hyper_fail.msg_cooling":"Il raffreddamento a {city} ha mollato in piena ondata di caldo. I server si sono spenti prima di diventare una grigliata.",
"hyper_fail.msg_dns":"Qualcuno ha mandato una modifica DNS a tutti i rack di {city} insieme. Era il DNS. È sempre il DNS.",
"hyper_fail.msg_squirrel":"Uno scoiattolo ha mandato in corto la cabina principale di {city}. Tutta la regione è al buio. Lo scoiattolo sta bene.",
"hyper_fail.msg_tag":"Uno stagista ha etichettato la regione di {city} come 'temporanea' e lo script di pulizia l'ha presa alla lettera.",
"hyper_fail.msg_ups":"La sala batterie di {city} ha fallito il test mensile guastandosi davvero. Tutta la regione è ripartita, lentamente.",
"hyper_fail.news_cats":"ULTIM'ORA: milioni di foto di gatti perse, giù la regione cloud di {city}",
"hyper_fail.news_save":"IN PRIMA PAGINA: giocatori perdono salvataggi da 400 ore nel crollo della regione di {city}",
"hyper_fail.news_spreadsheet":"SCANDALO: sparisce l'unica copia DEL foglio di calcolo dei contabili nel guasto di {city}",
"hyper_fail.news_wedding":"TRAGEDIA: video di matrimoni persi per sempre, giù la regione cloud di {city}",
