"hyper_freeze.fail_lag":"{game} è uscito con 900 ms di lag. Gli speedrunner ora fanno speed-walking. {name} non ride.",
"hyper_freeze.fail_meme":"Il lancio di {game} è crollato così forte da diventare un meme prima di diventare un gioco. {name} sta «valutando i partner».",
"hyper_freeze.fail_queue":"Il lancio di {game} di {name}: quattro milioni di giocatori in coda per il login, ne sono entrati tre. Le recensioni lo chiamano «un simulatore di sala d'attesa».",
"hyper_freeze.fail_refund":"Le richieste di rimborso per {game} superano i giocatori. Il CEO di {name} ha postato la tua pagina di stato.",
"hyper_inc.cert_cal":"Il promemoria per rinnovare il certificato della porta d'ingresso a {city} era nel calendario di qualcuno andato via nel 2023. Gli utenti vedono un avviso rosso e vanno altrove.",
"hyper_inc.cert_exp":"Il certificato TLS della tua porta d'ingresso a {city} è scaduto a mezzanotte. I browser mostrano una pagina rossa che fa paura; gli utenti fanno il giro verso un'altra porta, se c'è.",
"hyper_inc.dns_ttl":"Qualcuno ha messo ogni TTL di Route 66 a zero \"così le modifiche escono prima\". I name server si sono fusi; {n} tenant con DNS sono più o meno offline.",
"hyper_inc.dns_zone":"Route 66 è giù: un file di zona ha perso il punto finale. {n} tenant con DNS chiamano tutti insieme. Era il DNS. È sempre il DNS.",
"hyper_inc.melt_queue":"{game} è uscito e la coda di login di {name} è arrivata sulla Luna. La region a {city} è in fiamme e serve meno fino alla fine del lancio.",
"hyper_inc.melt_retry":"Tutti i giocatori di {game} hanno premuto riprova insieme. La tempesta di tentativi si è portata via la region a {city}; {name} dà la colpa al cloud, tu al pulsante riprova.",
"hyper_inc.pow_crane":"Una gru del cantiere accanto ha incontrato la sottostazione che alimenta {city}. {util} ci sta lavorando; nel frattempo la region serve la metà.",
"hyper_inc.pow_diesel":"{util} ha perso un trasformatore a {city}. I generatori sono partiti, poi sono rimasti a secco: il budget del gasolio è finito nella festa di Natale.",
"hyper_inc.pow_kite":"Una festa degli aquiloni si è impigliata nelle linee elettriche verso {city}. {util} dice che era un aquilone molto bello. La region serve la metà.",
"hyper_inc.press_hn":"Un thread sull'accaduto arriva a 3.000 commenti; 2.000 dicono che avrebbero fatto self-hosting.",
"hyper_inc.press_postmortem":"Il tuo postmortem promette di non dare colpe. Lo stagista non ne è così sicuro.",
"hyper_inc.press_status":"La tua pagina di stato è rimasta verde per tutto il tempo. Nessuno ci crede.",
"hyper_inc.press_trend":"\"Il cloud è giù?\" è in tendenza in tutto il mondo.",
"hyper_inc.storm_dedupe":"Il servizio di deduplicazione a {city} è stato deduplicato. La replica verso {b} rispedisce tutto, {x} volte il solito.",
"hyper_inc.storm_flag":"Un push di configurazione ha cambiato un flag a {city}: la region crede che la replica a {b} abbia dimenticato tutto, e le rimanda ogni cosa, {x} volte tanto.",
"hyper_inc.storm_yaml":"Qualcuno ha indentato una riga di YAML a {city}. Ora la replica verso {b} copia ogni oggetto {x} volte, per sicurezza.",
