"hyper_ops.o_fund":"Rispondi alle proteste",
"hyper_ops.o_fund_d":"Una protesta che i fondi per la comunità vincerebbero, fino al prezzo qui sotto, li riceve finché non è vinta. La simpatia non sposta traffico.",
"hyper_ops.o_rg":"Tieni d'occhio le region",
"hyper_ops.o_rg_desc":"Una region al limite o oltre passa al livello successivo, al massimo una al mese e solo a un livello che hai raggiunto due livelli fa, se megawatt e legge lo permettono e il mese resta in attivo; se manca corrente, si chiede presto alla compagnia elettrica. Altrimenti una nota nel rapporto.",
"hyper_ops.o_wave":"Wave per l'arretrato",
"hyper_ops.o_wave_desc":"Una coppia di region il cui arretrato di replica cresce oltre il limite riceve una wave in affitto tra le due, la più piccola che porta quel che mancava: una per turno, poi una settimana per smaltire. Il suo prezzo mensile conta nel budget e non porta mai il mese in perdita.",
"hyper_ops.p_days":"Di nuovo dopo",
"hyper_ops.p_how":"Quando è piena",
"hyper_ops.p_max":"Al massimo per protesta",
"hyper_ops.p_out":"Dopo",
"hyper_ops.p_ready":"Solo se pronta",
"hyper_ops.p_tb":"Arretrato oltre",
