"hyper_rivals.down_cert":"Un certificato che nessuno ha rinnovato ha buttato giù {rival} in {reg}. I loro tenant chiamano te.",
"hyper_rivals.down_dns":"Un solo record DNS ha buttato giù {rival} in tutta {reg}. I loro tenant chiamano te.",
"hyper_rivals.down_status":"La pagina di stato di {rival} per {reg} è tutta verde. Tutto il resto è in fiamme. I loro tenant chiamano te.",
"hyper_rivals.down_typo":"{rival} è giù in {reg}: qualcuno ha sbagliato a scrivere un comando durante una manutenzione di routine. I loro tenant chiamano te.",
