"hyper_rivals.job_gpus":"{rival} si è preso il training di {lab}: «Abbiamo le GPU. Beh, le avremo.»",
"hyper_rivals.job_thinking":"{rival} si è preso il training di {lab} mentre tu ci stavi ancora pensando.",
"hyper_rivals.poach_credits":"{name} è passato a {rival}: «Ci hanno promesso il 99,99999% di uptime. Per iscritto. In Comic Sans.»",
"hyper_rivals.poach_free_egress":"{name} è passato a {rival} per l'«egress gratis». È gratis per i primi tre byte.",
"hyper_rivals.poach_hoodie":"{rival} ti ha soffiato {name} al rinnovo con una felpa col logo e un anno di crediti gratis.",
"hyper_rivals.poach_keynote":"{rival} ti ha soffiato {name} con un keynote, una macchina del fumo e uno sconto che nessuno sa spiegare.",
"hyper_rivals.war_blog":"{rival} taglia i prezzi in {reg} del {p} e scrive un post sull'«ossessione per il cliente».",
"hyper_rivals.war_credits":"{rival} taglia i prezzi del cloud in {reg} del {p}: «Ora con il 20% di crediti gratis in più!»",
"hyper_rivals.war_free_tier":"{rival} lancia in {reg} un piano gratuito così gratuito che costa il {p} meno del tuo.",
