"ops.l_decom":{"one":"ha restituito una wave piccola su {where}","other":"ha restituito {n} wave piccole ({where})"},
"ops.l_fabric":{"one":"ha potenziato il fabric di {where}","other":"ha potenziato fabric di exchange {n} volte ({where})"},
"ops.l_freeze":{"one":"ha tenuto le mani lontane dalla rete per un change freeze (il grosso bottone rosso è coperto di nastro adesivo)","other":"ha tenuto le mani lontane dalla rete per {n} giorni di change freeze (ha coperto il grosso bottone rosso di nastro adesivo e ci si è seduto sopra)"},
"ops.l_optics":{"one":"ha acceso un canale su {where}","other":"ha acceso {n} canali ({where})"},
"ops.l_optswap":{"one":"ha scambiato un’ottica con una più grande su {where}","other":"ha scambiato {n} ottiche con altre più grandi ({where})"},
"ops.l_optup":{"one":"ha potenziato il line system su {where}","other":"ha potenziato {n} line system ({where})"},
"ops.l_peer":{"one":"ha fatto peering con una rete a {where}","other":"ha fatto peering con {n} reti a {where}"},
"ops.l_pie":{"one":"ha prenotato un lancio verso {where}","other":"ha prenotato {n} lanci ({where})"},
"ops.l_pni":{"one":"ha ordinato un PNI a {where}","other":"ha ordinato {n} PNI ({where})"},
"ops.l_ports":{"one":"ha aumentato una porta di peering a {where}","other":"ha aumentato le porte di peering {n} volte ({where})"},
"ops.l_repair":{"one":"ha accelerato una riparazione","other":"ha accelerato {n} riparazioni"},
"ops.l_routers":{"one":"ha potenziato i router a {where}","other":"ha potenziato i router in {n} posti ({where})"},
"ops.l_rs":{"one":"si è unito a un route server","other":"si è unito a {n} route server"},
"ops.l_snag":{"one":"si è bloccato su {where} e l'ha messo in pausa finché non dai un'occhiata","other":"si è bloccato su {n} ordini ({where}) e li ha messi in pausa finché non dai un'occhiata"},
"ops.l_transit":{"one":"ha aumentato il transit a {where}","other":"ha aumentato il transit {n} volte ({where})"},
"ops.l_waveup":{"one":"ha portato di una taglia una wave in affitto su {where}","other":"ha portato di una taglia {n} wave in affitto ({where})"},
"ops.mood_annie":"Annie ha risposto a tre domande prima che tu le facessi, dalla scrivania più vicina.",
"ops.mood_broke":"{name} ha già la lista della spesa per quando arriva il budget del mese prossimo.",
"ops.mood_busy":"{name} ha avuto una settimana piena ed è alla terza bevanda energetica.",
"ops.mood_kevin":"Kevin dice che nel 2001 era più tranquillo. Non lo era.",
"ops.mood_new":"{name} ha trovato la macchinetta del caffè e la CLI, in quest'ordine. Pronto quando vuoi.",
"ops.mood_oops":"{name} oggi va con i piedi di piombo. Nessuno nomini le descrizioni delle interfacce.",
"ops.mood_outage":"{name} guarda i grafici del guasto e ricarica la pagina di stato. Parecchio.",
"ops.mood_quiet":"{name} legge RFC in santa pace. I grafici sono piatti, come devono essere.",
"ops.mood_snag":"{name} ha trovato qualcosa di strano, ha messo in pausa quell'ordine e ti ha lasciato un post-it.",
"ops.mood_tracy":"Tracy è al terzo hop di un traceroute, con un solo asterisco per ora.",
"ops.o_caches":"Accetta cache gratuite",
"ops.o_caches_d":"Monta ogni cache gratuita che una rete offre, appena il suo traffico in quella città supera una soglia.",
"ops.o_decom":"Ritira i piccoli link paralleli",
"ops.o_decom_d":"Quando un link più grande tra due città è attivo, restituisci le wave piccole che non servono più. Mai una che un cliente noleggia o da cui dipende.",
"ops.o_fabric":"Ingrandisci i tuoi exchange",
"ops.o_fabric_d":"Potenzia il fabric di un exchange che gestisci quando il traffico supera il margine, o quando i posti sono finiti e una rete aspetta di entrare. Un fabric più grande porta più traffico e accoglie più membri paganti.",
"ops.o_ix":"Peering su ogni IX",
"ops.o_ix_d":"Ogni settimana: entra nei route server e chiedi il peering a ogni membro disponibile su ciascuna delle tue porte di exchange.",
"ops.o_optics":"Accendi più fibra",
"ops.o_optics_d":"Aggiungi ottiche alla dark fiber che scotta e accendi la fibra nuova il giorno della consegna.",
"ops.o_optup":"Potenzia il trasporto ottico",
"ops.o_optup_d":"Sulla fibra piena che va calda, o di cui i compratori sul mercato della capacità vogliono più di quanto possa vendere, porta il line system alla taglia successiva, o scambia i canali più piccoli con ottiche più grandi (le vecchie finiscono a scaffale). Scegli un line system e ogni fibra con uno più piccolo passa a quello. Cambiare line system spegne la fibra per un giorno, quindi solo dove il traffico può girarle intorno e nessun cliente ci passa, uno per notte.",
"ops.o_pie":"Tenere piene le croste",
"ops.o_pie_d":"Prenota lanci perché le tue croste restino piene mentre le torte vecchie si consumano: torte dal magazzino della fabbrica, la prima rampa libera, mai un volo di prova. Ognuno costa quanto fa pagare la scheda Croste.",
"ops.o_pni":"PNI con i grandi",
"ops.o_pni_d":"Ogni settimana: ordina un PNI con ogni rete disponibile che manda abbastanza traffico nei tuoi POP, alla taglia minima di ciascuna rete.",
"ops.o_ports":"Margine sulle porte di peering",
"ops.o_ports_d":"Tieni le porte PNI e IX sopra un multiplo del traffico di oggi: una porta singola in un POP con più router ne riceve una seconda in LAG, tutte le altre passano a una porta più grande.",
"ops.o_repair":"Accelera le riparazioni",
"ops.o_repair_d":"Paga la riparazione urgente di ogni guasto che ce l'ha, finché il budget regge.",
"ops.o_routers":"Router sempre avanti",
"ops.o_routers_desc":"Aggiungi un router, o passa alla generazione successiva dove un secondo router regge il traffico, quando carico o porte superano una soglia. Scegli un modello e ogni POP con uno più piccolo passa a quello, prima il più carico, nei limiti del budget.",
"ops.o_transit":"Margine di transit",
"ops.o_transit_d":"Tieni il transit di ogni POP sopra un multiplo del suo picco a 30 giorni: un membro LAG in più, o una porta più grande.",
"ops.o_waveup":"Wave in affitto più grandi",
"ops.o_waveup_d":"Porta una wave in affitto alla taglia successiva quando va al limite, a meno che sulla tratta ci sia o si stia costruendo fibra spenta tua.",
