"optx.l_d":"Pianificatori, giuntatori e un veterano dei cavi sottomarini che ha già visto ogni errore una volta. Quattro tratte alla volta, e raramente sbaglia.",
"optx.l_n":"Dipartimento di Fotonica",
"optx.m_d":"Un vero team ottico, con uno strumento di pianificazione e un furgone. Due tratte alla volta.",
"optx.m_dark":"Qualcuno ha sbagliato a digitare una config: {where} resta spenta fino a domani.",
"optx.m_n":"La Squadra Lambda",
"optx.m_over":"Roccia dove il rilievo diceva sabbia su {where}: il cantiere costa {cost} in più.",
"optx.m_slip":"I permessi per {where} hanno richiesto più tempo: il cantiere slitta di {n} giorni.",
"optx.s_d":"Due ingegneri e una giuntatrice a fusione. Una tratta alla volta, e nessun doppio controllo due volte.",
"optx.s_n":"Una giuntatrice e un foglio di calcolo",
"oq":"San Salvador ha un exchange ma ancora nessuno collegato, quindi il traffico tra due ISP locali di solito esce dal paese per incontrarsi.",
"or":"L’hub dei cavi sul Mar Rosso dell’Arabia Saudita. Sempre più cavi tra Europa, Africa e Asia fanno tappa qui invece che in Egitto.",
"os":"La capitale della Scozia. I cavi del Mare del Nord verso la Norvegia e le Fær Øer approdano lungo la costa.",
"ot":"Sei reti nella tabella di routing globale, e un gateway che porta la maggior parte del traffico del nord.",
"ou":"Piccolo, ricco e collegatissimo. Il suo unico confine di terra è con l’Arabia Saudita.",
"ov":"Una delle bande larghe domestiche più veloci del pianeta, e il mercato del peering più strano. Con il “sender pays”, i tre grandi ISP fanno pagare ogni gigabit che gli consegni, e qui il transit è tra i più cari al mondo.",
"ow":"La costa est del Sudafrica: surf, curry e la spiaggia dove approdano i cavi dell’Oceano Indiano.",
"own_cable.a_fishing_fleet_is_trawling_exactly":"Una flotta di pescherecci sta strascicando proprio dove devi posare.",
"own_cable.a_whale_has_parked_on_the":"Una balena si è parcheggiata sul percorso e non si sposta.",
"own_cable.storm_season_the_ship_is_sheltering":"Stagione delle tempeste. La nave è al riparo in porto, a giocare a carte.",
"own_cable.the_cable_ship_s_coffee_machine":"La macchina del caffè della nave posacavi si è rotta. Senza caffè non lavora nessuno.",
"own_cable.the_crew_fished_out_somebody_else":"L’equipaggio ha ripescato per sbaglio il cavo di qualcun altro e deve rimetterlo giù.",
"own_cable.the_seabed_survey_found_an_old":"Il rilievo del fondale ha trovato una vecchia mina. Una piccola, attentissima deviazione.",
"ox":"Il mercato più grande del Sud America, e casa di IX.brrr: gestito da una nonprofit, prezzi pubblici, e ci sono praticamente tutti.",
"oy":"Regole da internet sovrano: ogni POP vuole una scatola governativa nel rack, i video di Goggle sono rallentati e il firewall nazionale fa le esercitazioni.",
"oz":"Startup, techno e un numero sorprendente di data center in vecchi birrifici.",
"p":"{city} resta al buio",
"p0":"Qui approdano i cavi sottomarini per l’Africa e l’Asia.",
"p1":"Il primo cavo del Suriname approda a Totness, due ore a ovest lungo la costa, e prosegue verso la Guyana e Trinidad.",
"p2":"La costa ovest della Svezia, a metà strada tra Oslo e Copenaghen: qui passa la fibra tra Svezia e Norvegia.",
"p3":"La città federale svizzera governa da qui e fa peering da Zurigo, un’ora di treno più su.",
"p4":"Tahiti, nella Polinesia Francese. Un cavo corre a nord verso le Hawaii, e quello nuovo dal Cile all’Australia fa tappa qui: il trampolino tra il Sud America e l’Oceania.",
"p5":"Tango, bistecca e una folla fedelissima di ISP locali.",
"p6":"La città più grande della Tanzania e la porta sul mare per una mezza dozzina di paesi senza costa.",
"p7":"Il primo cavo di Tarawa è arrivato nel 2026: duemila chilometri fino a Nauru e Pohnpei, pagati da tre governi amici.",
"p8":"La capitale della pesca delle Aleutine. La fibra è arrivata nel 2023; prima, satelliti e pazienza.",
"p9":"Le Azzorre, in mezzo all’Atlantico. I cavi dalla Florida verso Lisbona e la Spagna fanno scalo qui: un POP spezza la traversata e ogni metà porta di più. Le mucche sono più dei server.",
"pa":"La capitale delle Bahamas, a un salto dalla Florida. Quasi tutti i cavi verso sud si fermano qui lungo la strada.",
"pb":"La città più grande a nord del Circolo polare artico. Il cavo russo Polar Express doveva partire da qui verso est; in acqua c’è solo il primo tratto. Posane uno tu.",
"pc":"Il fondo del paese, su linee elettriche costruite per una fonderia di alluminio. Qualcuno sta costruendo un campus IA da 280 MW in un pascolo fuori città, quindi i cavi arriveranno. Probabilmente.",
"pd":"In fondo alla mappa. Aria fresca, idroelettrico a buon mercato e tutto lo Stretto di Bass tra te e il continente.",
"pe":"La capitale degli affari dell’Africa occidentale francofona, con torri di vetro su una laguna e cinque cavi nella baia.",
"peering_desk.closed_desc":"Ogni richiesta di peering viene declinata, e niente route server. I clienti sentono dire che sei difficile da raggiungere, quindi ne chiamano meno.",
"peering_desk.open_desc":"Ogni rete che chiede ottiene una sessione, e i route server funzionano.",
"peering_desk.open_to_all":"Aperta a tutti",
"peering_desk.selective_desc":"Le reti piccole dell’exchange e i nuovi arrivati con PeeringDB aggiornato ottengono una sessione; le altre vengono declinate in silenzio. Niente route server: chiedi le reti che vuoi su ogni exchange.",
"pf":"Le Canarie, a un passo da Lisbona e dal Marocco. Quasi ogni cavo lungo la costa occidentale dell’Africa fa scalo qui, e il lungo tratto fino a Lagos diventa due tratti più corti.",
"pg":"La capitale, che costruisce campus AI su scala gigawatt. I dati degli utenti sauditi devono restare nel Regno, e ogni POP richiede una licenza telecom locale.",
"ph":"La capitale è qui, internet a trenta chilometri, a Cotonou, dove approdano i cavi e gira l’exchange.",
"pi":"La capitale dell’Acre, uno stato che secondo una battuta brasiliana non esiste. I tuoi traceroute dicono il contrario.",
