"pie.fp_3am":"Posto alle 3 di notte perché il sonno è un protocollo legacy. Le nostre torte sono il 40% più buone dello scorso trimestre.",
"pie.fp_astro":"Gli astronomi dicono che le nostre torte fanno photobombing nei loro telescopi. Hanno provato a guardare in mezzo?",
"pie.fp_backup":"La fatturazione è tornata dal backup di martedì scorso. Il piccolo {nick} è in punizione finché non impara le prepared statement.",
"pie.fp_baked":"{crust} è ben cotta. Prossima fermata: Marte. Probabilmente l'anno prossimo.",
"pie.fp_booster":"Il booster si è ribaltato all'atterraggio. Era un ribaltamento previsto. Lo chiamiamo recupero orizzontale rapido.",
