"pie.fp_leak":"Prossimo lancio: martedì, 6:42, rampa due, foto del carico in allegato. L'ufficio legale dice di cancellarlo. Non lo cancello.",
"pie.fp_leak_kid":"Il piccolo {nick} ha postato la data del prossimo lancio dal mio telefono. Bambini, eh. (Sono stato io.)",
"pie.fp_mars":"Marte l'anno prossimo. Pie su Marte. Prenota ora.",
"pie.fp_mars_kid":"Ho promesso al piccolo {nick} una festa di compleanno su Marte. L'anno prossimo. Sicuramente l'anno prossimo.",
"pie.fp_mars_slip":"Marte adesso è l'anno {n}. Marte è sempre stato l'anno {n}. Il pianeta rosso può aspettare.",
"pie.fp_promise":"Promessa: copertura totale entro l'anno {n}. Segnatevelo.",
"pie.fp_reg":"I regolatori sono solo firewall con il badge. Fatevi sotto.",
