"puzzles_weekly.ring":"Anello",
"pv":"La Città Giardino e la città più grande dell’Isola del Sud, che qui chiamano «la Terraferma» senza ridere. Tutto ciò che va verso l’Isola del Nord attraversa lo Stretto di Cook.",
"pw":"Il gateway di mezza Asia centrale: reti tagike, turkmene e afghane comprano tutte passando per Tashkent.",
"px":"Il centro geografico del Sud America, e una delle città più calde del Brasile. I chiller non hanno mai un giorno libero.",
"py":"Il centro geografico degli Stati Uniti. I data center stanno in vecchie miniere di calcare sottoterra: temperatura costante, niente tornado, e qualcuno continua a trovare le scarpe di Dorothy.",
"pz":"Il governo si è trasferito su per la collina a Gitega nel 2019; l’exchange e i data center sono rimasti a Bujumbura.",
"q":"A {city} mancano {g}",
"q0":"Il porto, il ponte e quasi tutti i data center del paese. La vera latenza è l’affitto.",
"q1":"La sede di governo più alta del mondo, a 3.600 m. I pendolari vanno in funivia, e anche un po’ della fibra.",
"q2":"La lunga strada verso Johannesburg: il traffico di Giuba percorre migliaia di chilometri prima di incontrare gran parte di internet.",
"q3":"La capitale delle Maldive, un metro sopra il mare e tappa dei cavi dall’India al Golfo e a Singapore.",
"q4":"Il centro di ovunque: niente mare, niente cavo, solo fibra lungo l’autostrada e una vecchia stazione del telegrafo.",
"q5":"La grande città più isolata della Terra. L’Asia è più vicina di Sydney.",
"q6":"Lo snodo del Nord, con il suo exchange e prese d’aria dei condizionatori molto umide. I cavi per l’Irlanda e la Danimarca arrivano sulla costa poco più su.",
"q7":"La città più settentrionale degli Stati Uniti, raggiunta dalla prima fibra sottomarina dell’Artico americano.",
"q8":"La capitale dei Territori del Nord-Ovest, in fondo alla fibra della valle del Mackenzie, posata lungo il fiume fino alla costa artica.",
"q9":"L’antica porta verso l’Europa dell’Est. I pacchetti fanno ancora un inchino educato quando passano.",
"qa":"L’unica capitale del Nordest lontana dal mare. Famosa per il caldo, con temporali e fulmini che tengono occupati gli scaricatori di sovratensione.",
"qb":"La porta sul Pacifico. Le Ande stanno tra lei e tutto il resto, e ogni tanto la terra trema.",
"qc":"La seconda città delle Filippine, raggiungibile solo con cavi nazionali. I tifoni ci passano andando verso nord.",
"qd":"La porta delle praterie tra Vancouver e il resto del Canada. Un chinook scioglie la neve in un pomeriggio, poi nevica di nuovo.",
"qe":"L’hub della Renania-Ruhr: più data center carrier-neutral di Amburgo o di Monaco, e a un’ora dal confine olandese, quindi la fibra fino ad Amsterdam è corta ed economica. Qui si ordina un’Altbier, mai una Kölsch.",
"qf":"La capitale delle Seychelles, su Mahé: 115 isole, tartarughe giganti e due cavi verso il continente.",
"qg":"La capitale delle Isole Salomone, su Guadalcanal. Il cavo per Sydney è arrivato solo pochi anni fa; prima era tutto satellite. La corrente è meno affidabile del cavo.",
"qh":"Il carrier hotel del Sud-Est. L’aeroporto più trafficato, il peering più trafficato a sud di Ashburn.",
"qi":"Qui, sulla costa basca, approdano i cavi transatlantici. L'exchange è a Madrid, quindi quasi tutto il traffico corre verso l'interno.",
"qj":"La Venezia del Brasile, tutta ponti e fiumi, con uno dei più grandi parchi tecnologici del paese nel suo vecchio porto.",
"qk":"L’intero paese è un’unica rete che annuncia una manciata di rotte, e le case normali non ci sono collegate.",
"ql":"Tutto il paese su un cavo: una diramazione di ACE, approdata nel 2011 e condivisa da tutti gli operatori.",
"qm":"La capitale dello Yukon, su un’unica lunga tratta di fibra lungo l’Alaska Highway: un taglio a sud della città e tutto il territorio aspetta.",
"qn":"Organizza la festa di São João più grande del mondo: un mese intero di forró ogni giugno. Ed è anche una città universitaria piena di ingegneri.",
"qo":"Il primo cavo di Timor Est si è acceso a luglio 2026: seicento chilometri fino al North-West Cable System dell’Australia.",
"qp":"Piccola, tropicale e la città australiana più vicina all’Asia. Qui approdano nuovi cavi per Singapore e Jakarta, accanto ai coccodrilli.",
"qq":"Tonga è appesa a un solo cavo dalle Figi. Nel 2022 un vulcano sottomarino l’ha tranciato e il paese è rimasto offline per settimane.",
"qr":"La capitale di Trinidad, all’estremità sud della catena di isole e a pochi chilometri dal Venezuela.",
"qs":"Dodicimila persone e il loro primo cavo, approdato ad agosto 2025 sulla strada da Tarawa a Pohnpei.",
"qt":"A venti minuti da tutto, tranne che da qualsiasi altro posto.",
"qu":"Città gemelle, un solo exchange e passerelle tra i palazzi: anche Minneapolis fa peering qui, e a gennaio nessuno esce a giuntare una fibra.",
"qv":"Due ore a nord di Stoccolma, una region cloud e una famosa capra di paglia.",
"qw":"Due milioni di persone in mezzo alla foresta pluviale, con una zona franca piena di fabbriche. La fibra segue i fiumi, e quando si rompe la squadra di riparazione parte in barca.",
"qx":"Due exchange rivali, uno all’università tecnica e uno commerciale, e quasi tutte le reti slovacche stanno su entrambi.",
"qy":"Tifoni, terremoti e tantissima gente sempre online.",
"qz":"Gli ingegneri di rete ucraini hanno tenuto in piedi internet tra blackout e cose molto peggiori. Generatori, fibra di scorta e ridondanza su tutto qui sono la norma, e la scena del peering è notoriamente tosta.",
"r":"Chiuso",
"r0":"Università, biotech e un carrier hotel che è sopravvissuto alla maggior parte dei suoi carrier.",
"r1":"Uruguay: fibra in quasi ogni casa, un portatile per ogni scolaro, e una telco di stato che gestisce quasi tutto.",
"r2":"Sempre online e servita male dal mare: in qualsiasi momento almeno uno dei suoi cavi sottomarini è rotto.",
"r3":"La capitale della Virginia, dove i cavi transatlantici di Virginia Beach arrivano nell’entroterra fino a un exchange neutrale: una porta per l’Europa più tranquilla di Ashburn.",
"r4":"Il calore di scarto finisce dritto nelle terme accanto.",
"r5":"Le pianure del Texas occidentale, terra a basso costo e un gigawatt di addestramento IA che ci cresce sopra.",
"r6":"Quando nel 2018 il suo unico cavo è stato tagliato, la Mauritania è rimasta quasi del tutto offline per due giorni.",
"r7":"Quando nel 2025 è arrivato il cavo, tutto il paese ha avuto internet gratis per un giorno per festeggiare.",
"r8":"Dove si incontrano Brasile, Argentina e Paraguay, accanto a cascate gigantesche e a una diga ancora più grande. L’energia costa poco, le pratiche doganali no.",
"r9":"Dove approdano i cavi dell’Africa orientale, che poi salgono in treno fino a Nairobi.",
"ra":"Dove il vento del Mare del Nord e l’energia sottomarina toccano terra, un campus cloud dietro la diga.",
"rb":"Dove i cavi del Sud America approdano davvero. Europa, Africa e USA arrivano a riva qui, poi fanno un lungo backhaul verso sud.",
"rc":"Dove approdano i cavi atlantici per il sud dell’Africa. Pinguini sulla spiaggia, distacchi programmati sulla rete elettrica.",
"rd":"Case bianche che salgono dal Mediterraneo. I cavi vanno a nord verso Marsiglia, e anche gran parte del traffico.",
"re":"Parchi eolici e aria fredda a nord di Pechino: i campus cloud della capitale.",
