"rg":"Collegata in quattro modi per meno di un milione di persone: EASSy, 2Africa e due cavi corti verso Mayotte.",
"rh":"Lo Zambia va a energia idroelettrica da un unico grande lago. Negli anni secchi il lago si abbassa, e anche la rete elettrica.",
