"sa":"Dismetti {city}…",
"sales.auto_ceo":"{name} firma le offerte che la tua rete può servire oggi, una prova al giorno. Rifiuta anche quelle sotto il tuo minimo, anche se ogni tanto ha già stretto la mano.",
"sales.auto_eng":"{name} firma le offerte che la tua rete può servire oggi, dopo averle provate sulla rete (una al giorno), e rifiuta quelle che pagano meno del tuo minimo.",
"sales.auto_shark":"{name} firma ogni offerta appena arriva, promesse comprese, finché puoi pagare la provvigione, e rifiuta quelle che pagano meno del tuo minimo.",
"sales.ceo_d":"Gratis, e convinto. Ogni paio di mesi firma un contratto enorme sul campo da golf con il 30% di sconto, spesso con una promessa che nessuno ha controllato, e ogni tanto firma un'offerta che avevi rifiutato. Ha opinioni. Non si può licenziare.",
"sales.ceo_n":"Il CEO, che vende meglio di chiunque",
"sales.ceo_s":"il CEO",
"sales.ceo_say_airport":"Appena atterrato. Non ho firmato niente, ma il Wi-Fi della lounge mi ha dato ottime sensazioni.",
"sales.ceo_say_blockchain":"Abbiamo pensato di mettere la tabella di routing su una blockchain?",
"sales.ceo_say_golf":"I contratti migliori si chiudono alla nona buca. Il NOC dovrebbe giocare più a golf.",
"sales.ceo_say_mbps":"Perché vendiamo gigabit? I megabit sembrano di più.",
"sales.ceo_say_napkin":"Ho fatto il prezzo del prossimo contratto su un tovagliolo. L'ingegneria sistemerà i dettagli.",
"sales.ceo_say_synergy":"Non vendiamo banda, vendiamo sinergia. Mettetelo sul sito.",
"sales.ceo_sky":"In orbita: una partita di golf su due la gioca con il Fondatore, per il contratto in orbita più grande che ci sta, con il 30% di sconto. I mercati nervosi gli costano: prezzi in orbita più bassi, e niente golf quando sono molto nervosi.",
"sales.eng_d":"Era un ingegnere di rete e ora ha il badge di ogni NOG. Ti iscrive a tutti (il biglietto lo paghi tu), porta tanti contratti piccoli e medi ma mai quelli davvero grandi, e vende solo ciò che la rete sa fare, così i clienti restano. I nerd adorano Dave. Tratta male.",
"sales.eng_n":"L'ingegnere diventato venditore-droide",
"sales.eng_s":"Dave",
"sales.eng_sky":"In orbita: vende solo dove la parabola di atterraggio ha spazio d'avanzo, e quei clienti restano come i nerd.",
"sales.ren_ceo":"{name} risponde alla rinegoziazione di un cliente tre giorni dopo l'inizio, sul campo da golf: più sconto di quanto chiesto in cambio di un contratto lungo il doppio, un sì veloce, o una lite dopo cui il cliente se ne va.",
"sales.ren_ceo_fight":"{name} ha detto a {cust} che con lui nessuno tratta. Se ne sono andati.",
"sales.ren_ceo_yes":"{name} ha detto sì a {cust} prima che qualcuno potesse controllare: {price}/mese.",
"sales.ren_eng":"{name} risponde alla rinegoziazione di un cliente tre giorni dopo l'inizio. I clienti nerd passano un pomeriggio con gli schemi della rete e di solito rinnovano a prezzo di mercato; gli altri ottengono lo sconto che chiedevano. Nessuno se ne va.",
"sales.ren_eng_cave":"{name} ha dato a {cust} lo sconto che chiedeva: {price}/mese. Restano.",
"sales.ren_eng_tech":"{name} ha passato un pomeriggio a mostrare la rete agli ingegneri di {cust}. Rinnovano a {price}/mese, senza sconto.",
"sales.ren_mid":"{name} è venuto incontro a {cust}: {price}/mese.",
"sales.ren_shark":"{name} risponde alla rinegoziazione di un cliente tre giorni dopo l'inizio, e non regala niente: quasi tutti rinnovano al vecchio prezzo, spesso con una nuova promessa, e ti fattura un mese di quanto ti ha fatto risparmiare. Alcuni se ne vanno, soprattutto i nerd.",
"sales.ren_shark_walk":"{name} ha fatto il duro con {cust}, e se ne sono andati.",
"sales.shark_d":"Porta i contratti più grandi a un quarto in più, e si prende un mese di ogni contratto come provvigione. Vende troppo: metà arriva con una promessa che la tua rete non mantiene ancora, e quei clienti se ne vanno prima. Ignora i nerd: niente clienti tecnici, niente incontri, e i peering desk ti chiedono un quarto di traffico in più. Vince quasi tutte le trattative.",
"sales.shark_n":"Lo squalo",
"sales.shark_s":"Chad",
"sales.shark_sky":"In orbita: chiama prima compagnie aeree e navi da crociera, alla taglia più grande e a un quarto in più, e a metà promette un cielo pieno prima che tu ce l'abbia. Brontolano finché non arriva.",
"sb":"Dismetti più POP…",
