"specialist.cable_broker":"Broker di cavi",
"specialist.cable_broker_desc":"Posa fibra a terra e cavi sotto il mare dal primo giorno, accendili e vendi la capacità ad altri operatori. Obiettivi propri; vinci Barone del Vetro: i tuoi cavi approdano su {n} continenti mentre gli operatori ti pagano {m} al mese. Tutto il resto si sblocca con il livello, come sempre.",
