"specialist.the_classic_game_grow_everywhere_and":"Il gioco classico: cresci ovunque, i clienti seguono il tuo livello e Tier 1 è la vittoria.",
"specialist.trading_firms_and_other_latency_customers":"Le società di trading e gli altri clienti latenza chiamano più spesso e pagano il {p}% in più. Vinci Velocità della luce: batti la latenza in affitto più veloce su {r} rotte finanziarie con la tua fibra mentre {c} clienti latenza ti pagano. Tier 1 conta ancora.",
