"supply_chain.chip_shortage_every_router_vendor_is":"<b>Carenza di chip!</b><br>Tutti i produttori di router aspettano gli stessi chip. Router nuovi e upgrade costano il 40% in più per {n} giorni. Tempi di consegna: “sì”.",
"supply_chain.every_cable_ship_is_booked":"<b>Tutte le navi posacavi sono prenotate.</b><br>Gli hyperscaler hanno noleggiato ogni nave posacavi e ogni squadra di scavo del pianeta. Nuove fibre e nuovi cavi costano il 30% in più per {n} giorni.",
"supply_chain.laser_shortage_the_factory_that":"<b>Carenza di laser!</b><br>La fabbrica che produce i laser di metà delle ottiche del mondo si è allagata. Le ottiche costano il 50% in più per {n} giorni. Le scorte sul tuo scaffale sono appena diventate il miglior investimento della tua vita.",
