"tr":"Interconnessioni private (PNI)",
"ts":"Quando è attivo annuncia il bersaglio in modo più specifico, così le inondazioni arrivano sul suo ingresso da {g} invece che sulle tue porte, e lui le pulisce. Il traffico pulito torna sul tuo backbone. Sblocca anche i contratti di protezione DDoS.",
