"tu":"Chiuderlo davvero?",
"tv":"Spegnerlo davvero?",
"tw":"Remote peering all’IX",
"tx":"Per ora {city} è un solo edificio. Un blackout, un guasto all’aria condizionata o un addetto alle pulizie con l’aspirapolvere spengono tutta la città, e un secondo router non aiuta. Un secondo data center dall’altra parte della città, unito dal tuo anello metropolitano, tiene su metà del POP.",
"ty":"Upgrade a rotazione: un router alla volta, zero downtime.",
