"u5":"Servito a {city}",
"u6":"serve {v}",
"u7":"Chiudi questo POP: link, porte e cache spariscono con lui, e ogni cliente che ne dipende viene lasciato andare, con una penale di recesso anticipato.",
"u8":"Passa a sempre attivo",
"u9":"Passa a CN-Too premium <small>prezzo {x}× · ~3% di perdita verso la Cina</small>",
"ua":"Passa a on-demand <small>più economico</small>",
"ub":"Il modello decide la tua interfaccia più veloce e quanto può inoltrare questo POP. Più router aggiungono capacità e sopravvivono ai crash.",
"uc":"La Nearly Broadband Network se ne tiene il {pct} per l’ultimo miglio.",
"ud":"La gabbia standard contiene {n} router. Ognuno in più richiede un ampliamento: l'installazione costa il 50% in più e paghi {mo}/mese in più per spazio ed energia.",
"ue":"Questo chassis ci mette una vita a fare il boot: i crash durano di più, e sostituire l’unico router qui richiede 3 giorni. Un secondo router lo nasconde.",
"uf":"Questo POP ha {n} router, tutti quelli che l'edificio riesce ad alimentare. Per crescere ancora passa a un modello più grande.",
